def fmt(v,d=5):
 if v is None or isinstance(v,float) and not np.isfinite(v):return '—'
 return f'{v:.{d}f}' if isinstance(v,(float,np.floating)) else str(v)
def table(rows,cols):
 out=['| '+' | '.join(label for k,label in cols)+' |','| '+' | '.join('---' for k,label in cols)+' |']
 for r in rows:out.append('| '+' | '.join(fmt(r.get(k)).replace('|','/').replace('\n',' ') for k,label in cols)+' |')
 return '\n'.join(out)+'\n'
